import {bindDismissibleDetails} from '/detail-interactions.js';
import {triggerSettings} from '/trigger-settings.js';
import {MAP_CONFIG,chainInfo,socialReach,markerAppearance} from './map-markers.js';
import {channelCharts,setupChannelCharts} from './channel-charts.js';
import {channelSummary} from './channel-metrics.js';
import {SOCIAL_CONFIG,SOCIAL_BANDS,socialIndex,socialBand} from './social-heat.js';
import {PRIORITIES,REVENUE_BANDS,revenueBand} from './intelligence-rules.js';
const STAGES={announced:'Announced',planning:'Planning / approvals',construction:'Fit-out / construction',preopening:'Pre-opening',partially_open:'Partially open',open:'Operating',unknown:'Status unconfirmed',conflict:'Conflicting evidence',closed:'Closed'};
const GROUPS=[['all','All records'],['upcoming','Upcoming signals'],['partial','Partially open'],['operating','Operating'],['review','Needs verification']];
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=u=>{try{let x=new URL(u);return ['http:','https:'].includes(x.protocol)?x.href:null}catch{return null}};
const filterKeys=['stage','confidence','type','region','chain','dateFilter','sort','revenue'];
let filtered=[],excluded=[],showExcluded=false,account={canEdit:false,signedIn:false},photoObserver;
const placeRequests=new Map();
const findRecord=id=>records.find(r=>r.id===id)||excluded.find(r=>r.id===id)?.venue;
const chainTag=r=>{const info=chainInfo(r,records);return (info.isChain?`<span class="brand-tag chain-tag">Chain · ${info.count} locations</span>`:'')+(r.chain?.brand?`<span class="brand-tag">${esc(r.chain.kind)} · ${esc(r.chain.brand)}</span>`:'<span class="venue-sub">Chain status not established</span>');};
const openingBlock=r=>`<strong class="date-value">${esc(r.openingInfo?.label||r.opening||'Date unconfirmed')}</strong><span class="date-status ${r.openingInfo?.status==='Reported actual'?'actual':''}">${esc(r.openingInfo?.status||'Date unconfirmed')}</span><span class="small-note">${esc(r.dateNote||'Exact date not verified')}</span>`;
const areaBlock=r=>{const a=r.areaInfo;return a?.sqm?`<strong>${Number(a.sqm).toLocaleString()} m²</strong><span class="small-note">${esc(a.scope)}</span>${a.source?sourceLink({url:a.source,publisher:'Area source'}):''}<span class="small-note">${esc(a.note||'Reported area; not measured by Pisell.')}</span>`:'<strong class="muted">Not published</strong><span class="small-note">No verified area in checked sources</span>'};
const editAction=(r,full=false)=>account.canEdit?`<button class="${full?'quiet':'remove-button'}" data-${showExcluded?'restore':'remove'}="${esc(r.id)}" aria-label="${showExcluded?'Restore':'Delete'} ${esc(r.name)}">${full?(showExcluded?'Restore venue':'Delete & exclude'):(showExcluded?'↶':'×')}</button>`:'';
const photoShell=r=>`<figure class="venue-photo" data-photo="${esc(r.id)}"><div class="photo-loading">${r.placeId?'Loading photo…':r.photoReference?'Project reference':'Photo not verified'}</div></figure>`;
async function getPlace(r){
 if(!r.placeId)return null;if(placeRequests.has(r.placeId))return placeRequests.get(r.placeId);
 const request=fetch('https://places.googleapis.com/v1/places/'+encodeURIComponent(r.placeId),{headers:{'X-Goog-Api-Key':window.PISELL_MAPS_KEY,'X-Goog-FieldMask':'id,photos,location,addressComponents,googleMapsUri,userRatingCount,rating'}}).then(async res=>{if(!res.ok)throw Error('Place details unavailable');return res.json()});
 placeRequests.set(r.placeId,request);request.catch(()=>placeRequests.delete(r.placeId));return request;
}
function watchPhotos(root){
 if(!photoObserver)photoObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){photoObserver.unobserve(e.target);loadPhoto(e.target)}}),{rootMargin:'120px'});
 root.querySelectorAll('[data-photo]').forEach(el=>photoObserver.observe(el));
}
async function loadPhoto(el){
 const r=findRecord(el.dataset.photo);if(!r)return;
 try{
  const place=await getPlace(r),photos=place?.photos||[];
  const photo=photos[Number(el.dataset.photoIndex||0)%photos.length];
  if(photo){
   const uri='https://places.googleapis.com/v1/'+photo.name+'/media?maxWidthPx=640&key='+encodeURIComponent(window.PISELL_MAPS_KEY);
   const authors=photo.authorAttributions||[];
   el.innerHTML=`<a href="${esc(safeUrl(place.googleMapsUri)||'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(r.name)+'&query_place_id='+encodeURIComponent(r.placeId))}" target="_blank" rel="noopener"><img src="${esc(uri)}" alt="${esc(r.name)} — ${r.mapPrecision==='mall'?'shopping centre reference':'Google place photo'}" loading="lazy"></a><figcaption><span class="maps-attribution" translate="no">Google Maps</span>${authors.map(a=>`<a href="${esc(safeUrl(a.uri)||'https://maps.google.com/')}" target="_blank" rel="noopener">${esc(a.displayName)}</a>`).join(' · ')}${r.mapPrecision==='mall'?'<span>Mall reference</span>':''}</figcaption>${photos.length>1&&el.closest('.detail-photo')?`<button class="photo-arrow previous" data-photo-step="-1" aria-label="Previous photo">‹</button><button class="photo-arrow next" data-photo-step="1" aria-label="Next photo">›</button><span class="photo-position">${Number(el.dataset.photoIndex||0)+1} / ${photos.length}</span>`:''}`;
   el.querySelectorAll('[data-photo-step]').forEach(button=>button.onclick=()=>{el.dataset.photoIndex=(Number(el.dataset.photoIndex||0)+Number(button.dataset.photoStep)+photos.length)%photos.length;loadPhoto(el)});
  }else if(r.photoReference?.url){el.innerHTML=`<a href="${esc(safeUrl(r.photoReference.source))}" target="_blank" rel="noopener"><img src="${esc(safeUrl(r.photoReference.url))}" alt="${esc(r.name)} project or brand reference" loading="lazy"></a><figcaption>${esc(r.photoReference.label)}</figcaption>`}
  else el.innerHTML='<div class="photo-loading">Photo not published</div>';
  el.querySelector('a>img')?.addEventListener('error',()=>{el.innerHTML='<div class="photo-loading">Photo unavailable</div><button class="link-button" data-retry-photo>Retry</button>';el.querySelector('button').onclick=()=>{placeRequests.delete(r.placeId);loadPhoto(el)}});
 }catch{el.innerHTML='<div class="photo-loading">Photo unavailable</div><button class="link-button" data-retry-photo>Retry</button>';el.querySelector('button').onclick=()=>loadPhoto(el)}
}
async function loadCouncil(r){try{const p=await getPlace(r);if(location.hash!==('#'+encodeURIComponent(r.id)))return;const c=p?.addressComponents?.find(c=>c.types.includes('administrative_area_level_2'));$('#live-council').innerHTML=c?`${esc(c.longText)}<span class="small-note">Google address details</span>`:'Not verified';}catch{if($('#live-council'))$('#live-council').textContent='Not available'}}
function initOptions(){for(const [id,values,label]of [['region',[...new Set(records.map(r=>r.region))].sort(),'All regions'],['chain',[...new Set(records.map(r=>r.chain?.brand).filter(Boolean))].sort(),'All brands']])$('#'+id).innerHTML=`<option value="all">${label}</option>`+(id==='chain'?'<option value="none">Chain not established</option>':'')+values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');}
async function loadAccount(){try{const res=await fetch('/api/session',{cache:'no-store'});if(res.ok)account=await res.json();if(account.canEdit){const out=await fetch('/api/exclusions',{cache:'no-store'});if(out.ok)excluded=(await out.json()).records;}}catch{account={canEdit:false,signedIn:false}}}
let toastTimer;
function toast(message,undo){clearTimeout(toastTimer);$('#toast').hidden=false;$('#toast').innerHTML=`<span>${esc(message)}</span>${undo?'<button id="undo-action">Undo</button>':''}<button id="dismiss-toast" aria-label="Dismiss">×</button>`;$('#dismiss-toast').onclick=()=>$('#toast').hidden=true;if(undo)$('#undo-action').onclick=undo;toastTimer=setTimeout(()=>$('#toast').hidden=true,15000)}
async function changeExclusion(id,remove,button){
 if(button){button.disabled=true;button.setAttribute('aria-busy','true')}
 try{const res=await fetch('/api/exclusions/'+encodeURIComponent(id),{method:remove?'POST':'DELETE',headers:{'X-Requested-With':'Pisell'}});if(!res.ok){const data=await res.json();throw Error(data.error||'Unable to save your change.')}
  const fresh=await fetch('/api/data',{cache:'no-store'});if(!fresh.ok)throw Error('Saved. Reload the page to refresh the list.');records=(await fresh.json()).venues;await loadAccount();if($('#detail').open)closeDetail();render();toast(remove?'Venue excluded. Future imports will skip this location.':'Venue restored.',remove?()=>changeExclusion(id,false):null);
 }catch(e){toast(e.message)}finally{if(button){button.disabled=false;button.removeAttribute('aria-busy')}}
}
document.addEventListener('click',e=>{const remove=e.target.closest('[data-remove]'),restore=e.target.closest('[data-restore]');if(remove)changeExclusion(remove.dataset.remove,true,remove);if(restore)changeExclusion(restore.dataset.restore,false,restore)});
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render()});
$('#privacy-button').onclick=()=>$('#privacy').showModal();$('#close-privacy').onclick=()=>$('#privacy').close();
const miniCard=r=>`<article class="mini-card"><button class="name-button" data-id="${esc(r.id)}">${esc(r.name)}</button><span class="venue-sub">${esc(r.suburb)} · ${esc(r.region)}</span>${badge(r.phase)}${socialBlock(r)}${revenueBlock(r)}<span class="small-note">Opening: ${esc(r.opening)}</span>${chainTag(r)}</article>`;
for(const sel of ['#map-list','#calendar-view'])$(sel).addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)openDetail(b.dataset.id,b)});
function renderCalendar(){
 const [y,m]=state.month.split('-').map(Number);$('#calendar-month').value=state.month;$('#calendar-title').textContent=new Date(y,m-1,1).toLocaleDateString('en-AU',{month:'long',year:'numeric'});
 const start=(new Date(y,m-1,1).getDay()+6)%7,days=new Date(y,m,0).getDate();
 const known=filtered.filter(r=>r.openingInfo?.precision==='day'&&r.openingInfo.date?.startsWith(state.month));
 let html=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(day=>`<div class="weekday">${day}</div>`).join('');
 for(let i=0;i<Math.ceil((start+days)/7)*7;i++){const day=i-start+1,key=state.month+'-'+String(day).padStart(2,'0');html+=day<1||day>days?'<div class="calendar-cell outside"></div>':`<div class="calendar-cell"><span class="day-number">${day}</span>${known.filter(r=>r.openingInfo.date===key).map(r=>`<button class="calendar-event ${r.openingInfo.status==='Reported actual'?'actual':''}" data-id="${esc(r.id)}"><strong>${esc(r.name)}</strong><span>${esc(r.openingInfo.status)}</span></button>`).join('')}</div>`;}
 $('#calendar-grid').innerHTML=html;
 const windows=filtered.filter(r=>['window','month','by'].includes(r.openingInfo?.precision));
 $('#date-windows').innerHTML=`<div class="window-heading"><h3>Opening windows</h3><span class="muted">${known.length} day-dated events this month · Windows stay off exact calendar days</span></div><div class="compact-list">${windows.map(r=>`<article class="mini-card"><button class="name-button" data-id="${esc(r.id)}">${esc(r.name)}</button>${openingBlock(r)}${r.openingInfo.date?`<button class="link-button" data-jump-month="${esc(r.openingInfo.date.slice(0,7))}">Show month →</button>`:''}</article>`).join('')||'<p class="muted">No opening windows match these filters.</p>'}</div>`;
 const undated=filtered.filter(r=>r.openingInfo?.precision==='unknown');$('#undated-count').textContent=`Date unconfirmed · ${undated.length} venues`;$('#undated-list').innerHTML=undated.map(miniCard).join('');
}
function shiftMonth(delta){const [y,m]=state.month.split('-').map(Number),date=new Date(y,m-1+delta,1);state.month=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0');render()}
$('#prev-month').onclick=()=>shiftMonth(-1);$('#next-month').onclick=()=>shiftMonth(1);$('#calendar-month').onchange=e=>{if(/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){state.month=e.target.value;render()}};$('#calendar-today').onclick=()=>{state.month=new Date().toLocaleDateString('en-CA',{timeZone:'Australia/Melbourne'}).slice(0,7);render()};
$('#calendar-view').addEventListener('click',e=>{const b=e.target.closest('[data-jump-month]');if(b){state.month=b.dataset.jumpMonth;render()}});
let mapsPromise,map,markers=[],mapGeneration=0,positions=new Map(),mapFailed=false;
function loadMaps(){if(mapsPromise)return mapsPromise;mapsPromise=new Promise((resolve,reject)=>{window.pisellMapsReady=resolve;window.gm_authFailure=()=>{mapFailed=true;$('#map-status').textContent='Google Maps could not authorise this website. Venue files remain available below.';reject(Error('Map access unavailable'))};const script=document.createElement('script');script.src='https://maps.googleapis.com/maps/api/js?key='+encodeURIComponent(window.PISELL_MAPS_KEY)+'&loading=async&libraries=marker&callback=pisellMapsReady&v=weekly&language=en&region=AU';script.async=true;script.onerror=()=>reject(Error('Map could not load. Check your connection and retry.'));document.head.append(script)});return mapsPromise;}
const stageColor=r=>r.phase==='open'?'#18734a':['announced','planning','construction','preopening','partially_open'].includes(r.phase)?'#c43214':'#8a5200';
function fitMap(){if(!map||!positions.size)return;const bounds=new google.maps.LatLngBounds();filtered.forEach(r=>{if(positions.has(r.id))bounds.extend(positions.get(r.id))});if(!bounds.isEmpty()){map.fitBounds(bounds,45);google.maps.event.addListenerOnce(map,'idle',()=>{if(map.getZoom()>16)map.setZoom(16)})}}
$('#fit-map').onclick=fitMap;
async function renderMap(){renderMapLegend();const generation=++mapGeneration,rows=[...filtered];$('#map-list').innerHTML=rows.map(r=>`<article class="mini-card"><button class="name-button" data-id="${esc(r.id)}">${esc(r.name)}</button><span class="venue-sub">${esc(r.suburb)} · ${esc(r.region)}</span>${badge(r.phase)}${chainTag(r)}${socialBlock(r)}<span class="small-note">Opening: ${esc(r.opening)}</span><span class="small-note">${r.mapPrecision==='mall'?'Mall location · tenant position unconfirmed':r.placeId?'Matched venue listing':'Exact location not verified'}</span>${r.placeId?`<button class="link-button" data-locate="${esc(r.id)}">Locate on map</button>`:''}</article>`).join('');
 $('#map-status').textContent='Loading Google Maps…';
 try{await loadMaps();if(generation!==mapGeneration||state.view!=='map')return;if(mapFailed)return;
 if(!map){map=new google.maps.Map($('#google-map'),{center:{lat:-37.8136,lng:144.9631},zoom:10,mapId:'DEMO_MAP_ID',streetViewControl:false,mapTypeControl:false,gestureHandling:'cooperative'});map.addListener('zoom_changed',()=>$('#google-map').classList.toggle('show-marker-names',map.getZoom()>=MAP_CONFIG.labelZoom));map.addListener('dragstart',()=>{if($('#detail').open)closeDetail(false)});}
 markers.forEach(m=>m.map=null);markers=[];positions=new Map();let completed=0,failed=0;
 const tasks=rows.filter(r=>r.placeId);let cursor=0;
 await Promise.all(Array.from({length:4},async()=>{while(cursor<tasks.length){const r=tasks[cursor++];try{const p=await getPlace(r);if(generation!==mapGeneration)return;if(!p?.location)throw Error('No location');const pos={lat:p.location.latitude,lng:p.location.longitude};positions.set(r.id,pos);const el=document.createElement('button');const appearance=markerAppearance(r,records);el.className='map-pin pin-'+appearance.shape;el.style.setProperty('--pin-color',appearance.color);el.dataset.venue=r.id;el.dataset.shape=appearance.shape;el.title=r.name+' · '+appearance.label+(appearance.chain.isChain?' · Chain: '+appearance.chain.count+' locations':'')+(r.mapPrecision==='mall'?' · Mall reference':'');el.setAttribute('aria-label',el.title);el.innerHTML=appearance.shape==='star'?'<svg viewBox="0 0 40 40" aria-hidden="true"><path d="M20 2 25.5 13.5 38 15.3 29 24.2 31.1 37 20 31 8.9 37 11 24.2 2 15.3 14.5 13.5Z"/></svg>':`<span aria-hidden="true">${r.mapPrecision==='mall'?'M':''}</span>`;el.onclick=e=>{e.stopPropagation();openDetail(r.id,el);};const name=document.createElement('span');name.className='map-name';name.textContent=r.name;el.append(name);markers.push(new google.maps.marker.AdvancedMarkerElement({map,position:pos,content:el,title:el.title,zIndex:appearance.upcoming?100:10}));}catch{failed++}completed++;if(generation===mapGeneration)$('#map-status').textContent=`${positions.size} located · ${rows.length-positions.size} not yet located${completed<tasks.length?' · Loading…':''}`;}}));
 if(generation===mapGeneration){fitMap();$('#map-status').textContent=`${positions.size} located · ${rows.length-positions.size} without a verified pin${failed?' (some lookups unavailable)':''}`;}
 }catch(e){$('#map-status').textContent=e.message;$('#google-map').innerHTML='<div class="empty"><p>Map unavailable. You can still open every venue file.</p><button class="quiet" id="retry-map">Retry map</button></div>';$('#retry-map').onclick=()=>{mapsPromise=null;mapFailed=false;$('#google-map').innerHTML='';renderMap()}}
}
$('#map-list').addEventListener('click',e=>{const b=e.target.closest('[data-locate]');if(b){const p=positions.get(b.dataset.locate);if(p&&map){map.panTo(p);map.setZoom(15)}else toast('This location is still loading or could not be verified.')}});
let records=[],metadata={},state={group:'all',stage:'all',confidence:'all',type:'all',q:'',view:'list',region:'all',chain:'all',dateFilter:'all',sort:'priority',revenue:'all',mapColor:'social',month:new Date().toLocaleDateString('en-CA',{timeZone:'Australia/Melbourne'}).slice(0,7)},lastTrigger;
const matchesGroup=(r,g)=>g==='all'||(g==='upcoming'&&['announced','planning','construction','preopening'].includes(r.phase))||(g==='partial'&&r.phase==='partially_open')||(g==='operating'&&r.phase==='open')||(g==='review'&&(r.confidence==='low'||['unknown','conflict'].includes(r.phase)));
const level=c=>({high:'High confidence',medium:'Moderate confidence',low:'Needs verification'}[c]||'Needs verification');
const badge=(p,n)=>`<span class="badge ${esc(p)}">${esc(n||STAGES[p]||p)}</span>`;
function sourceLink(s){const u=safeUrl(s.url);return u?`<a class="source-link" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(s.short||s.publisher)} ↗</a>`:`<strong>${esc(s.publisher)}</strong>`}
function readState(){const p=new URLSearchParams(location.search);for(const k of ['group','stage','confidence','type','q','view','region','chain','dateFilter','sort','month','revenue','mapColor'])if(p.has(k))state[k]=p.get(k);if(!GROUPS.some(g=>g[0]===state.group))state.group='all';if(state.stage!=='all'&&!STAGES[state.stage])state.stage='all';if(!['all','high','medium','low'].includes(state.confidence))state.confidence='all';if(state.type!=='all'&&!records.some(r=>r.type===state.type))state.type='all';if(!['list','map','calendar'].includes(state.view))state.view='list';if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(state.month))state.month=new Date().toISOString().slice(0,7);state.mapColor='social';if(!['all',...REVENUE_BANDS.map(b=>b.id)].includes(state.revenue))state.revenue='all';$('#map-color').value=state.mapColor;$('#search').value=state.q;for(const k of filterKeys)$('#'+k).value=state[k];}
function writeState(){const p=new URLSearchParams();for(const[k,v]of Object.entries(state))if(v&&v!=='all')p.set(k,v);history.replaceState(null,'',location.pathname+(p.size?'?'+p:'')+location.hash)}
function render(){
 const base=showExcluded?excluded.map(x=>x.venue):records;
 $('#summary').innerHTML=GROUPS.map(([g,label])=>`<button class="metric" data-group="${g}" aria-pressed="${state.group===g}"><span>${label}</span><strong>${records.filter(r=>matchesGroup(r,g)).length}</strong></button>`).join('');
 const q=state.q.toLowerCase();filtered=base.filter(r=>matchesGroup(r,state.group)&&(state.stage==='all'||r.phase===state.stage)&&(state.confidence==='all'||r.confidence===state.confidence)&&(state.revenue==='all'||revenueBand(r).id===state.revenue)&&(state.type==='all'||r.type===state.type)&&(state.region==='all'||r.region===state.region)&&(state.chain==='all'||(state.chain==='none'?!r.chain?.brand:r.chain?.brand===state.chain))&&(state.dateFilter==='all'||(state.dateFilter==='day'?r.openingInfo?.precision==='day':state.dateFilter==='unknown'?r.openingInfo?.precision==='unknown':['month','window','by'].includes(r.openingInfo?.precision)))&&(!q||[r.name,r.suburb,r.address,r.region,r.chain?.brand,r.assessment,r.type,...(r.aliases||[])].join(' ').toLowerCase().includes(q)));
 if(state.sort==='date')filtered.sort((a,b)=>(a.openingInfo?.date||'9999').localeCompare(b.openingInfo?.date||'9999'));
 if(state.sort==='area')filtered.sort((a,b)=>(b.areaInfo?.sqm||0)-(a.areaInfo?.sqm||0));
 if(state.sort==='social')filtered.sort((a,b)=>(socialReach(b,records).score??-1)-(socialReach(a,records).score??-1));
 if(state.sort==='audience')filtered.sort((a,b)=>(channelSummary(b).find(m=>m.metric==='followers')?.value??-1)-(channelSummary(a).find(m=>m.metric==='followers')?.value??-1));
 if(state.sort==='name')filtered.sort((a,b)=>a.name.localeCompare(b.name));
 $('#result-count').textContent=`${filtered.length} ${showExcluded?'excluded ':''}records · ${metadata.asOf||'12 Sep 2026'}`;
 document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view===state.view));
 $('.table-wrap').hidden=state.view!=='list'||!filtered.length;$('#map-view').hidden=state.view!=='map';$('#calendar-view').hidden=state.view!=='calendar';$('#empty').hidden=filtered.length>0;
 if(state.view==='list'){
 $('#venues').innerHTML=filtered.map(r=>`<tr><td><div class="venue-identity">${photoShell(r)}<div><button class="name-button" data-id="${esc(r.id)}">${esc(r.name)}</button><span class="venue-sub">${esc(r.suburb||'Location unconfirmed')} · ${esc(r.region)}</span>${chainTag(r)}<span class="venue-sub">${esc(r.address||'Address not confirmed')}</span></div></div></td><td>${badge(r.phase)}${r.phaseNote?`<span class="small-note">${esc(r.phaseNote)}</span>`:''}</td><td>${openingBlock(r)}</td><td>${areaBlock(r)}</td><td>${revenueBlock(r)}</td><td>${socialBlock(r)}</td><td><span class="confidence ${esc(r.confidence)}">${level(r.confidence)}</span>${r.sources.slice(0,2).map(sourceLink).join('')}<button class="name-button small-note" data-id="${esc(r.id)}">${r.sources.length} sources ↗</button></td><td><button class="row-open" data-id="${esc(r.id)}" aria-label="Open ${esc(r.name)} details">↗</button>${editAction(r)}</td></tr>`).join('');watchPhotos($('#venues'));
 }
 if(state.view==='map')renderMap();if(state.view==='calendar')renderCalendar();
 $('#manage-actions').innerHTML=account.canEdit?`<button class="quiet" id="show-excluded" aria-pressed="${showExcluded}">${showExcluded?'Back to venues':'Excluded · '+excluded.length}</button>`:account.signedIn?'<span class="muted">Read-only account</span>':'<a class="quiet" href="/signin-with-chatgpt?return_to='+encodeURIComponent(location.pathname+location.search)+'" target="_top">Sign in to manage</a>';
 if($('#show-excluded'))$('#show-excluded').onclick=()=>{showExcluded=!showExcluded;render()};writeState();if(window.parent!==window)window.parent.postMessage({type:'pisell-venue-state',value:location.search+location.hash},location.origin);
}
function openDetail(id,trigger){channelUI.hide();const r=findRecord(id);if(!r)return;lastTrigger=trigger||document.activeElement;
 $('#detail-body').innerHTML=`<div class="detail-photo">${photoShell(r)}</div>${badge(r.phase)}<h2>${esc(r.name)}</h2><p class="muted">${esc(r.address||r.suburb||'Address not confirmed')}</p><span class="confidence ${esc(r.confidence)}">${level(r.confidence)}</span><dl class="field-grid"><div><dt>Opening date</dt><dd>${openingBlock(r)}</dd></div><div><dt>Date basis</dt><dd>${esc(r.dateNote||'Unverified')}</dd></div><div><dt>Social channels</dt><dd>${socialBlock(r)}</dd></div><div><dt>Annual turnover · AUD</dt><dd>${revenueBlock(r,true)}</dd></div><div><dt>Area</dt><dd>${areaBlock(r)}</dd></div><div><dt>Suburb / region</dt><dd>${esc(r.suburb)} · ${esc(r.region)}</dd></div><div><dt>Council / LGA</dt><dd id="live-council">${r.placeId?'Checking address…':'Not verified'}</dd></div><div><dt>Brand network</dt><dd>${chainTag(r)}<span class="small-note">${esc(r.chain?.basis)}</span></dd></div><div><dt>Venue type</dt><dd>${esc(r.type||'Indoor play venue')}</dd></div><div><dt>Last checked</dt><dd>${esc(r.checked||metadata.asOf)}</dd></div></dl>${r.zones?.length?`<h3>What is open?</h3>${r.zones.map(z=>`<div class="zone-row"><strong>${esc(z.name)}</strong><span>${esc(z.status)}</span></div>`).join('')}`:''}${r.areaInfo?.additional?.map(a=>`<p><strong>${Number(a.sqm).toLocaleString()} m²</strong> · ${esc(a.scope)} ${sourceLink({url:a.source,publisher:"Area source"})}</p>`).join('')||''}${r.photoNote?`<p class="small-note">${esc(r.photoNote)}</p>`:''}<div class="detail-actions">${editAction(r,true)}</div>${socialDetails(r)}<h3>Assessment</h3><p>${esc(r.assessment)}</p>${r.detail?`<p>${esc(r.detail)}</p>`:''}<h3>Source trail <span class="muted">· ${r.sources.length}</span></h3>${r.sources.map(s=>`<article class="evidence-card">${sourceLink(s)}<p>${esc(s.claim||'Venue identity and location reference. Read the source for its current information.')}</p><div class="evidence-meta">${esc(s.channel||'Public source')} · ${esc(s.access||'Read')}<br>Published: ${esc(s.date||'Not stated')} · Checked: ${esc(s.checked||metadata.asOf)}</div></article>`).join('')}${r.unknowns?.length?`<h3>Still to verify</h3><ul>${r.unknowns.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${r.next?`<h3>Next step</h3><p>${esc(r.next)}</p>`:''}<p class="small-note">V0 · Collected venue record. Interest, system problems and purchase intent have not been established by this research.</p>`;
 watchPhotos($('#detail-body'));loadCouncil(r);channelUI.loadMaps($('#detail-body'),r);if(!$('#detail').open)$('#detail').show();history.replaceState(null,'',location.pathname+location.search+'#'+encodeURIComponent(id));}
function closeDetail(restoreFocus=true){channelUI.hide();$('#detail').close();history.replaceState(null,'',location.pathname+location.search);if(restoreFocus)lastTrigger?.focus()}
function reset(){const view=state.view,month=state.month;state={group:'all',stage:'all',confidence:'all',type:'all',q:'',view,month,region:'all',chain:'all',dateFilter:'all',sort:'priority',revenue:'all',mapColor:state.mapColor};$('#search').value='';for(const k of filterKeys)$('#'+k).value=state[k];render()}
$('#summary').addEventListener('click',e=>{let b=e.target.closest('[data-group]');if(b){state.group=b.dataset.group;render()}});
$('#venues').addEventListener('click',e=>{let b=e.target.closest('[data-id]');if(b)openDetail(b.dataset.id,b)});
$('#search').addEventListener('input',e=>{state.q=e.target.value;render()});
for(const k of filterKeys)$('#'+k).addEventListener('change',e=>{state[k]=e.target.value;render()});
$('#reset').onclick=reset;$('#empty-reset').onclick=reset;$('#close-detail').onclick=closeDetail;$('#detail').addEventListener('cancel',e=>{e.preventDefault();closeDetail()});
$('#coverage-button').onclick=()=>$('#coverage').showModal();$('#close-coverage').onclick=()=>$('#coverage').close();
async function init(){try{let data;if($('#venue-data'))data=JSON.parse($('#venue-data').textContent);else{const res=await fetch('/api/data',{cache:'no-store'});if(!res.ok)throw Error('Data unavailable');data=await res.json();}records=data.venues;metadata=data.meta;$('#stage').innerHTML='<option value="all">All stages</option>'+Object.entries(STAGES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');$('#type').innerHTML='<option value="all">All venue types</option>'+[...new Set(records.map(r=>r.type))].sort().map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');
 $('#coverage-body').innerHTML=`<h2>Coverage &amp; evidence</h2><p>${esc(metadata.summary||'Research in progress. Evidence is being cross-checked.')}</p><div class="field-grid"><div><dt>Checked</dt><dd>${esc(metadata.asOf)}</dd></div><div><dt>Scope</dt><dd>Greater Melbourne</dd></div></div><h3>Source coverage</h3><table><thead><tr><th>Source</th><th>What was checked</th></tr></thead><tbody>${(metadata.coverage||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.note)}</td></tr>`).join('')}</tbody></table><h3>Social channel scan · 13 Sep 2026</h3><p>147 venue records checked; 142 operator pages and 285 social URLs requested. Public channel counts were recorded for 107 venues, including shared brand accounts. Instagram followers and lifetime posts, Facebook page likes, check-ins and discussion figures remain separate measures. TikTok, RedNote and YouTube account counts were not verified in this run. This is not a completed 30-day heat sample.</p><h3>Turnover coverage</h3><p>Venue-level annual AUD turnover is separate from group income, taxable income, profit and asking price. ATO corporate transparency mainly covers entities with total income of A$100 million or more. Ordinary venue tax returns are not a public database. Grey means unknown or not comparable; it never means zero.</p><p>No current annual venue turnover has been verified in this snapshot. Initial checks covered ATO availability and selected public disclosures, not a completed financial investigation of every venue.</p><p><a href='https://www.ato.gov.au/businesses-and-organisations/corporate-tax-measures-and-assurance/large-business/corporate-tax-transparency/report-of-entity-tax-information' target='_blank' rel='noopener'>ATO public report coverage ↗</a></p><h3>How to read the stages</h3><p>One venue can open in sections. An operating court or café does not prove the play area is open. Planning approval does not prove construction. A page date can be provisional.</p><h3>Confidence</h3><p>High: a relevant operator, landlord or official record supports the stated claim. Moderate: useful evidence still needs corroboration. Needs verification: old, incomplete, conflicting or directory-only information. Confidence in a venue's identity does not confirm its opening date.</p><h3>Known gaps</h3><ul>${(metadata.gaps||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
 initOptions();await loadAccount();readState();render();if(location.hash)openDetail(decodeURIComponent(location.hash.slice(1)));}catch(e){$('#result-count').textContent='The venue list could not be loaded.';$('#empty').hidden=false;$('#empty').innerHTML='<h2>Unable to load this snapshot</h2><p>Please reload the page.</p><button class="primary" onclick="location.reload()">Reload</button>';}}

init();

function revenueLabel(r){const a=r.revenueInfo;if(a?.amount!=null&&a?.periodType==='year')return 'A$'+Number(a.amount).toLocaleString('en-AU');return revenueBand(r).id==='unknown'?'Annual turnover unknown':revenueBand(r).label;}
function revenueBlock(r,full=false){const a=r.revenueInfo,b=revenueBand(r);return `<span class="revenue-label"><i class="legend-dot" style="background:${b.color}"></i>${esc(revenueLabel(r))}</span>${a?.periodLabel?`<span class="small-note">${esc(a.periodLabel)} · ${esc(a.status)} · ${esc(a.scope)}</span>`:''}${full?`<span class="small-note">${esc(a?.note||'No verified annual turnover for this venue. Individual financial research is pending.')}</span>${a?.source?sourceLink({url:a.source,publisher:'Financial source'}):''}${(a?.observations||[]).map(o=>`<article class="evidence-card"><strong>${esc(o.label)}</strong><p>${esc(o.note)}</p>${sourceLink({url:o.source,publisher:o.publisher})}<span class="small-note">${esc(o.status)} · Checked ${esc(o.checked)}</span></article>`).join('')}`:''}`;}
function renderMapLegend(){$('#map-legend').innerHTML=`<span><i class="legend-star">★</i> Not yet open / partially open</span><span><i class="legend-square"></i> Chain · 3+ locations</span><span><i class="legend-dot" style="background:var(--text)"></i> Other venue</span>${MAP_CONFIG.bands.map(b=>`<span><i class="legend-dot" style="background:${b.color}"></i> ${esc(b.label)}</span>`).join('')}<span><i class="legend-dot" style="background:${MAP_CONFIG.unknown.color}"></i> ${esc(MAP_CONFIG.unknown.label)}</span><details class="map-method"><summary>Social reach · Rainbow Town = 100 ⓘ</summary><p>Colour estimates public social presence using Instagram followers and Facebook page likes. Each available measure is divided by Rainbow Town’s matching measure, then the ratios are averaged × 100. Only same-day observations are compared; missing channels are omitted, never zero. This is a reach proxy, not measured 30-day engagement or revenue. Shared brand accounts describe the brand, not a single branch. Chain means 3+ distinct non-closed locations in this directory, counted across all filters; it does not establish common ownership. A star takes precedence when the venue or play area is not fully open.</p></details>`;$('#map-color').value='social';}
$('#map-color').onchange=e=>{state.mapColor=e.target.value;render()};
$('#trigger-button').onclick=()=>{const dialog=$('#trigger-settings');if(!dialog.open)dialog.showModal();triggerSettings({host:$('#trigger-body'),canEdit:account.canEdit,notify:toast,api:async(path,options={})=>{const response=await fetch(path,{...options,headers:{'Content-Type':'application/json'}});const value=await response.json();if(!response.ok)throw Error(value.error||'Unable to save.');return value;}});};
$('#close-triggers').onclick=()=>$('#trigger-settings').close();

function socialLabel(r){const h=socialIndex(r,records);return h.score===null?'Awaiting sample':String(h.score)+(h.reference?' · Benchmark':'');}
function socialBlock(r){const h=socialIndex(r,records),counts=channelSummary(r);return `<button class="social-heat social-trigger" data-social="${esc(r.id)}" aria-expanded="false" aria-label="Channel data for ${esc(r.name)}">${counts.length?counts.map(m=>`<strong>${m.approximate?'≈ ':''}${Number(m.value).toLocaleString()} <span>${esc(m.label)}</span></strong>`).join(''):`<strong>${esc(socialLabel(r))}</strong>`}<span class="small-note">${counts.length?'View channel charts ↗':esc(h.status)}</span>${socialReach(r,records).score!==null?`<span class="small-note">Social reach: ${socialReach(r,records).score}${socialReach(r,records).shared?' · Brand account':''}</span>`:''}</button>`;}

function socialDetails(r){const h=socialIndex(r,records);return `${channelCharts(r,records.find(x=>x.id===SOCIAL_CONFIG.benchmarkId))}<details class="social-method"><summary>Social heat · basis &amp; sources</summary><p><strong>${esc(SOCIAL_CONFIG.benchmarkName)} = 100</strong>. This is your comparison reference, not a measured visitor count or revenue estimate. Braeside is a separate venue.</p><p>30-day publication window. Compare the same platforms, sampling protocol and observation date. Likes + comments: 50%; distinct customer / creator mentions: 30%; venue posts: 20%. Each measure is divided by the reference's matching measure, then combined. Platforms have equal weight within the stated sample.</p><p>Counts refer to visible engagement on posts published in that window, not all engagement generated during the month. Followers and lifetime totals do not determine this score. Missing data stays unknown; branch-ambiguous content is excluded. Known paid campaigns and giveaways are reported separately. High attention may include negative discussion.</p>${h.sample?`<p>Observed: ${esc(h.sample.observedOn)} · Protocol: ${esc(h.sample.protocolId)}</p>${h.sample.platforms.map(p=>`<article class="evidence-card"><strong>${esc(p.name)}</strong><p>${SOCIAL_CONFIG.metrics.map(m=>esc(m.label)+': '+Number(p.metrics[m.key]).toLocaleString()).join(' · ')}</p>${p.sources.map(url=>sourceLink({url,publisher:'Sample source'})).join('')}</article>`).join('')}`:'<p class="muted">No comparable 30-day sample has been recorded yet. Reference 100 is user-defined; other venue scores remain pending.</p>'}${(r.socialInfo?.observations||[]).map(o=>`<article class="evidence-card">${sourceLink({url:o.source,publisher:o.publisher})}<p>${esc(o.note)}</p><span class="small-note">${esc(o.status)} · Checked ${esc(o.checked)}</span></article>`).join('')}</details>`;}

const channelUI=setupChannelCharts({findRecord,reference:()=>records.find(x=>x.id===SOCIAL_CONFIG.benchmarkId),getPlace,detail:$('#detail')});


bindDismissibleDetails({dialog:$('#detail'),close:closeDetail});
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===window.parent&&e.data?.type==='pisell-dismiss-details'&&$('#detail').open)closeDetail(false);});
